export function Avatar({
  name = "{{name}}",
  initials = "{{initials}}",
  shape = "{{shape}}",
  color = "{{color}}",
  size = {{size}},
  icon = {{icon}},
}) {
  const radius = { circle: "50%", rounded: "22%", square: "0" }[shape] ?? "50%";
  return (
    <span role="img" aria-label={name} style={{
      display: "inline-flex", alignItems: "center", justifyContent: "center",
      background: color, color: "#241430", width: size, height: size,
      fontSize: size * 0.4, fontWeight: 600, borderRadius: radius,
      overflow: "hidden", flex: "none", fontFamily: "system-ui, sans-serif",
    }}>
      {icon ? (
        <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" style={{ width: "65%", height: "65%" }}>
          <circle cx="12" cy="8" r="4" /><path d="M4 20c0-4.4 3.6-8 8-8s8 3.6 8 8" />
        </svg>
      ) : (
        <span aria-hidden="true">{initials}</span>
      )}
    </span>
  );
}
